/**
 * Navigation-module types that widen the shared contracts in `src/core/types.ts`.
 * Everything here is structurally assignable to its core counterpart, so consumers that
 * only know the core types work unchanged; consumers importing from `src/nav` get the extras.
 */
import type { Airport, FlightPlan, Geodetic, NavRadioState, Navaid, Runway } from '../core/types';

/** `Runway.ils` widened with provenance and the frequency in kHz (the radios' unit). */
export type IlsInfo = NonNullable<Runway['ils']> & {
  /** true when generated by `synthesizeIls` rather than imported from real data */
  synthetic: boolean;
  /** localizer frequency in kHz (= round(frequencyMHz * 1000)) */
  frequencyKHz: number;
};

/** One landing direction of a physical runway. */
export interface RunwayEnd {
  /** e.g. "28R" */
  ident: string;
  /** pavement end of this direction (the landing threshold before displacement), geodetic */
  threshold: Geodetic;
  /** true heading flown when landing on this end, deg */
  headingDeg: number;
  /** displaced threshold distance along the runway from `threshold`, m */
  displacedThresholdM: number;
  /** ident of the opposite end, e.g. "10L" */
  oppositeIdent: string;
  /** index (0 = low-numbered "le" end, 1 = "he" end) in the parent runway's `ends` */
  index: 0 | 1;
  /** physical runway length, m */
  lengthM: number;
  /** ILS serving this end if any */
  ils?: IlsInfo;
}

/** A physical runway: the core `Runway` oriented to its low-numbered end plus both ends. */
export interface RunwayRecord extends Runway {
  /** OurAirports pair id, e.g. "10L/28R" */
  id: string;
  ends: [RunwayEnd, RunwayEnd];
  ils?: IlsInfo;
}

/** `Airport` whose runways carry both ends. */
export interface AirportRecord extends Omit<Airport, 'runways'> {
  runways: RunwayRecord[];
}

/** `Navaid` with the extra columns the data carries. `position.alt` is the station elevation. */
export interface NavaidRecord extends Navaid {
  /** ICAO ident of the associated airport, or '' */
  associatedAirport: string;
  /** true for VOR-DME, VORTAC, DME, TACAN and NDB-DME */
  hasDme: boolean;
}

/** Marker beacon currently received. */
export type MarkerBeacon = 'outer' | 'middle' | 'inner' | null;

/** `NavRadioState` with localizer back-course and marker-beacon information. */
export interface NavRadioStateEx extends NavRadioState {
  /** true when the aircraft is behind the localizer antenna (reverse sensing applies) */
  backCourse: boolean;
  marker: MarkerBeacon;
  /** great-circle (ground) distance to the station, m */
  distanceM: number;
  /** true when `dmeNm` comes from a received DME (VOR-DME/VORTAC/DME/TACAN/NDB-DME or an ILS); a plain VOR or NDB has none */
  dmeValid: boolean;
}

/** `FlightPlan` with whole-route totals. */
export interface FlightPlanEx extends FlightPlan {
  /** sum of all leg lengths, m */
  totalDistanceM: number;
  /** distance to the active waypoint plus all remaining legs, m */
  remainingDistanceM: number;
  /** ETE to the final waypoint, s (Infinity when ground speed is ~0) */
  eteTotalS: number;
  /** true when the last waypoint has been passed */
  complete: boolean;
  /** the active leg is a direct-to, flown from the position where D→ was activated */
  directTo: boolean;
  /**
   * the direct-to target is not part of the stored flight plan ("off-route" D→): `waypoints` is
   * then `[target]` while the stored plan waits, inactive, in `FlightPlanner.waypoints`
   */
  offRoute: boolean;
  /** FROM point of the active leg (previous waypoint, D→ origin or OBS course origin) */
  legFrom: Geodetic;
  /** GPS OBS course, deg true, while OBS mode suspends sequencing; null otherwise */
  obsCourseDeg: number | null;
  /** increments whenever the waypoints, the active leg, D→ or OBS change (cheap change detection) */
  version: number;
}

/** Loads a data file by its path relative to the site root (e.g. `data/airports.json`). */
export type NavDataLoader = (path: string) => Promise<unknown>;
